$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
git -C $repo fetch origin --prune
$targets=@(
  @{b='fix/heaven-gate-concurrency-20260929';s='486e672c14f8cb3422f1dea92600d4c9256bc3d4'},
  @{b='integration/complete-mod-workflows-main-20260929';s='febcf269db162f8d82030bf7c0c5e2b16d05751f'}
)
$deleted=@();$skipped=@()
foreach($t in $targets){
  $line=(git -C $repo ls-remote origin "refs/heads/$($t.b)")
  if(-not $line){$skipped += @{branch=$t.b;reason='already-absent'};continue}
  $actual=($line -split '\s+')[0]
  if($actual -ne $t.s){$skipped += @{branch=$t.b;reason='tip-changed';expected=$t.s;actual=$actual};continue}
  git -C $repo push origin --delete $t.b
  if($LASTEXITCODE -ne 0){throw "delete failed: $($t.b)"}
  $deleted += $t.b
}
git -C $repo fetch origin --prune
@{deleted=$deleted;skipped=$skipped;remaining=@(git -C $repo for-each-ref --format='%(refname:short)' refs/remotes/origin | ? {$_ -notmatch 'origin/HEAD'})}|ConvertTo-Json -Depth 5
